DELETE FROM document_types WHERE codigo IN ('CPF_CARTAO','TITULO_ELEITOR','CERTIDAO_CIVIL','COMPROVANTE_ESCOLARIDADE','CERTIFICADO_RESERVISTA','ACORDO_JORNADA','NOTA_FISCAL','CARTAO_CNPJ','CONTRATO_SOCIAL','GUIA_INSS','PROGRAMA_SST','PROTOCOLO_ENTREGA','OFICIO','ALVARA_LICENCA')
  AND NOT EXISTS (SELECT 1 FROM documents d WHERE d.document_type = document_types.codigo);
ALTER TABLE document_types DROP COLUMN origem, DROP COLUMN pistas, DROP COLUMN criado_em, DROP COLUMN revisado_em;
